  'Import JSON, HTML, ZIP archives, or folders from ChatGPT/OpenAI, Claude/Anthropic, Google AI Studio, Gemini Takeout, OpenRouter, LM Studio, Grok, Meta, and Venice. ThreadShelf Local Reader and ChatGPT Export Processor formats are supported. Subfolders are included; account metadata files are skipped automatically.':
    {
      hu: 'JSON-, HTML-, ZIP-fájlok vagy mappák importálása a ChatGPT/OpenAI, Claude/Anthropic, Google AI Studio, Gemini Takeout, OpenRouter, LM Studio, Grok, Meta és Venice szolgáltatásokból. A ThreadShelf Local Reader és ChatGPT Export Processor formátumai is támogatottak. Az almappákat is feldolgozza; a fiókmetaadatokat automatikusan kihagyja.',
      de: 'JSON, HTML, ZIP-Archive oder Ordner von ChatGPT/OpenAI, Claude/Anthropic, Google AI Studio, Gemini Takeout, OpenRouter, LM Studio, Grok, Meta und Venice importieren. ThreadShelf Local Reader und ChatGPT Export Processor werden unterstützt. Unterordner werden einbezogen, Kontometadaten automatisch übersprungen.',
      ja: 'ChatGPT/OpenAI、Claude/Anthropic、Google AI Studio、Gemini Takeout、OpenRouter、LM Studio、Grok、Meta、Venice の JSON、HTML、ZIP、フォルダーをインポートできます。ThreadShelf Local Reader と ChatGPT Export Processor 形式にも対応。サブフォルダーを含め、アカウントのメタデータは自動でスキップします。',
      fr: 'Importez JSON, HTML, ZIP ou dossiers de ChatGPT/OpenAI, Claude/Anthropic, Google AI Studio, Gemini Takeout, OpenRouter, LM Studio, Grok, Meta et Venice. Les formats ThreadShelf Local Reader et ChatGPT Export Processor sont pris en charge. Les sous-dossiers sont inclus ; les métadonnées de compte sont ignorées automatiquement.',
      ru: 'Импорт JSON, HTML, ZIP и папок из ChatGPT/OpenAI, Claude/Anthropic, Google AI Studio, Gemini Takeout, OpenRouter, LM Studio, Grok, Meta и Venice. Поддерживаются форматы ThreadShelf Local Reader и ChatGPT Export Processor. Вложенные папки включаются, метаданные аккаунта пропускаются автоматически.',
    },
