      de: '— Laden Sie den Google-Drive-Ordner „Google AI Studio“ herunter, entpacken und indexieren Sie ihn. Dateien ohne Endung sind zulässig. Textchats und Imagen-Eingabeverläufe werden unterstützt.',
      ja: '— Google Drive の「Google AI Studio」フォルダーをダウンロードし、展開して索引化します。拡張子なしのファイルも使用できます。テキストチャットと Imagen のプロンプト履歴に対応しています。',
