      de: 'Auch ausgeschaltet werden Hervorhebungen, Unterstreichungen, Listen, Links, Code und Tabellen mit einfachem Markdown formatiert. Komplexe Formeln, Diagramme und Widgets bleiben als lesbarer Quelltext sichtbar.',
