  'this optional cache is separate from conversations and search data. it stores images only on the server and groups them by collection.':
    {
      hu: 'Ez az opcionális gyorsítótár elkülönül a beszélgetésektől és a keresési adatoktól. Csak a kiszolgálón tárol képeket, gyűjteményenként csoportosítva.',
      de: 'Dieser optionale Cache ist von Unterhaltungen und Suchdaten getrennt. Bilder werden nur auf dem Server nach Sammlung gespeichert.',
      ja: 'この任意のキャッシュは会話や検索データとは独立しています。画像はサーバー上だけに保存され、コレクション別に管理されます。',
      fr: 'Ce cache facultatif est séparé des conversations et des données de recherche. Les images sont stockées uniquement sur le serveur, par collection.',
      ru: 'Этот необязательный кэш отделён от разговоров и поисковых данных. Изображения хранятся только на сервере по коллекциям.',
    },
